import urllib.request, urllib.error, json
for url in ['https://openrouter.ai/api/v1/openapi.json','https://openrouter.ai/api/v1/models/typesafe/jev-1.13/endpoints','https://openrouter.ai/api/v1/decisions', 'https://openrouter.ai/api/v1/systemone']:
    try:
        req=urllib.request.Request(url, data=b'{}',headers={'Content-Type':'application/json'}) if url.endswith(('decisions','systemone')) else url
        with urllib.request.urlopen(req,timeout=15) as r: data=r.read().decode()
        if 'openapi' in url:
            open('/tmp/incident-openrouter-openapi.json','w').write(data)
            print(url, [p for p in json.loads(data).get('paths', {}) if any(w in p for w in ['decision','systemone'])])
        else: print(url, data[:6500])
    except urllib.error.HTTPError as e: print(url,e.code,e.read().decode()[:1500])
PY"
